import { test, expect } from '@playwright/test'
import { loginAsAdmin, waitForPageLoading } from '../fixtures/auth-helpers.js'

/**
 * 返回首页（顶栏 navbar__ghost-btn「返回首页」）行为验证（bug #5983）。
 *
 * 用户复现场景：登录进入管理端，当前停在首页/待办页，点顶栏「返回首页」无反应。
 * 期望：通过参数配置 sys.portal.index.url 读取门户地址并整页跳转到门户首页。
 *
 * 为避免真实跳转到外部门户整页离开，本用例拦截门户地址并拦截配置接口的返回，
 * 断言：① 点击会发起 getByKey 配置请求；② 读到 http(s) 地址后整页跳到门户。
 */

const PORTAL_URL_KEY = 'sys.portal.index.url'
const FAKE_PORTAL_URL = 'http://portal.e2e.local/home'

/** 拦截参数配置接口，稳定返回指定门户地址，避免依赖真实配置 */
async function stubPortalConfig(page, portalUrl) {
  await page.route('**/system/config/getByKey**', async (route) => {
    const body = route.request().postData() || ''
    if (body.includes(PORTAL_URL_KEY)) {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ code: 200, msg: 'ok', data: portalUrl })
      })
      return
    }
    await route.continue()
  })
}

test.describe('顶栏「返回首页」跳转门户（bug #5983）', () => {
  test.setTimeout(90000)

  test('读到门户配置时点返回首页会整页跳转门户，而不是原地无反应', async ({ page }) => {
    await loginAsAdmin(page)
    await waitForPageLoading(page)

    const goHomeBtn = page.locator('button.navbar__ghost-btn', { hasText: '返回首页' }).first()
    await expect(goHomeBtn).toBeVisible({ timeout: 20000 })

    // 记录点击时是否真的发起了配置请求（修复前 goHome 直接 push('/index')，不会请求配置）
    const configReq = page.waitForRequest(
      (req) => req.url().includes('/system/config/getByKey') && (req.postData() || '').includes(PORTAL_URL_KEY),
      { timeout: 15000 }
    )

    await stubPortalConfig(page, FAKE_PORTAL_URL)

    const currentUrlBefore = page.url()
    await goHomeBtn.click()

    // ① 必须发起 getByKey 请求
    await configReq

    // ② 整页跳转到门户地址（location.replace，URL 变为 mock 门户）
    await expect
      .poll(() => page.url(), { timeout: 15000 })
      .toContain('portal.e2e.local')

    expect(page.url()).not.toBe(currentUrlBefore)
  })

  test('未配置门户地址时点返回首页回到管理端首页，不原地卡死', async ({ page }) => {
    await loginAsAdmin(page)
    await waitForPageLoading(page)

    const goHomeBtn = page.locator('button.navbar__ghost-btn', { hasText: '返回首页' }).first()
    await expect(goHomeBtn).toBeVisible({ timeout: 20000 })

    // 配置返回空字符串 → 走兜底回管理端首页
    await stubPortalConfig(page, '')

    await goHomeBtn.click()

    await page.waitForLoadState('domcontentloaded')
    // 兜底路径应停留在管理端（不报错、不白屏），hash 路由仍在应用内
    await expect(page.locator('#app')).toBeVisible({ timeout: 15000 })
    const hash = await page.evaluate(() => window.location.hash)
    expect(hash.startsWith('#/')).toBe(true)
    expect(page.url()).not.toContain('portal.e2e.local')
  })
})

